            "in": "header",
            "type": "string"
          },
          {
            "name": "ApiSignature",
            "description": "This signature is generated with the SHA256 algorithm and sent in the header.",
            "required": true,
            "in": "header",
            "type": "string"
          },
          {
            "name": "clientId",
            "description": "clientId used to request the access token",
            "required": true,
            "in": "header",
            "type": "string"
          },
          {
            "name": "Authorization",
            "description": "Bearer access token",
            "required": true,
            "in": "header",
            "type": "string"
          },
          {
            "x-amf-mediaType": "application/json",
            "in": "body",
