                "fiscalCode": "541321",
                "nationalityCountryCode": "ESP",
                "address": {
                  "cityCode": "MA",
                  "countryCode": "ESP",
                  "postalCode": "28043",
                  "street": "Roman",
                  "streetLetter": "B",
                  "streetNumber": 1
                },
                "identityDocument": {
                  "deliveryDate": "2020-11-27T15:49:52.795Z",
                  "documentNumber": "50770750K",
                  "expiryDate": "2032-11-27T15:49:52.795Z",
                  "code": "513",
                  "deliveryCountryCode": "ESP",
                  "deliveryCityCode": "MAD",
                  "documentTypeCode": "NICD",
                  "isDefault": true
                },
                "identityDocumentContent": [
                  {
                    "fileContent": "qwerqwerqwer",
                    "type": "IDENTITY_DOCUMENT_FRONT"
                  },
                  {
                    "fileContent": "2347guwbjf",
                    "type": "IDENTITY_DOCUMENT_BACK"
