                    "deliveryCityCode": {
                      "description": "Code of delivery city",
                      "type": "string"
                    },
                    "deliveryCountryCode": {
                      "description": "Iso 3 Code of delivery country",
                      "type": "string"
                    },
                    "code": {
                      "description": "Identity document code",
                      "type": "string"
                    },
                    "deliveryDate": {
                      "description": "Document delivery date",
                      "type": "string",
                      "format": "date-time"
                    },
                    "expiryDate": {
                      "description": "Document expiry date",
                      "type": "string",
                      "format": "date-time"
                    },
