                    "REJECTED_BAD_REQUEST",
                    "REJECTED_BY_AML",
                    "UNEXPECTED_ERROR"
                  ],
                  "type": "string"
                },
                "foundCustomerCode": {
                  "description": "code of customer if found",
                  "type": "string"
                },
                "foundCustomerIdentityDocumentCode": {
                  "description": "code of identity document of the customer if found",
                  "type": "string"
                },
                "similarCustomerIdentityDocumentCode": {
                  "description": "code of identity document of the customer if exists",
                  "type": "string"
                },
                "savedCustomerCode": {
                  "description": "Created code of the new customer",
                  "type": "string"
                },
                "similarCustomerCode": {
                  "description": "code of similar customer if exists",
                  "type": "string"
                },
                "amlResult": {
                  "enum": [
                    "NOT_SET",
                    "PASSED",
                    "NOT_PASSED",
                    "PASSED_WITH_FLAGS"
                  ],
                  "type": "string"
                }
              }
            }
          },
          "500": {
            "description": "Internal Server Error",
            "x-amf-mediaType": "application/json",
            "schema": {
              "description": "Error",
              "example": {
                "code": 29500,
                "message": "Internal error",
                "reason": "Something went wrong in the system during the execution"
              },
              "type": "object",
              "properties": {
                "reason": {
                  "description": "Error Reason",
                  "type": "string"
                },
                "code": {
                  "description": "Error code",
                  "type": "integer",
                  "format": "int32"
                },
                "message": {
                  "description": "Error Message",
                  "type": "string"
                }
              }
            }
