              "description": "Error",
              "example": {
                "code": 29401,
                "message": "Unauthorized",
                "reason": "Security parameter is missing or requestor doesn't have permissions to call this resource"
              },
              "type": "object",
              "properties": {
                "reason": {
                  "description": "Error Reason",
                  "type": "string"
                },
                "code": {
                  "description": "Error code",
                  "type": "integer",
                  "format": "int32"
                },
                "message": {
                  "description": "Error Message",
                  "type": "string"
                }
              }
            }
          },
          "400": {
            "description": "Bad request",
            "x-amf-mediaType": "application/json",
            "schema": {
              "description": "Error",
              "example": {
                "code": 29400,
                "message": "Bad Request",
                "reason": "invalid identity Document Content type"
