              "type": "object",
              "properties": {
                "reason": {
                  "description": "Error Reason",
                  "type": "string"
                },
                "code": {
                  "description": "Error code",
                  "type": "integer",
                  "format": "int32"
                },
                "message": {
                  "description": "Error Message",
                  "type": "string"
                }
              }
            }
          }
        }
